-- ULTRASTABLE-SCHEMA-1: generated by `node scripts/product_boundary.mjs --schema` from the live qnfo-audit schema of product/boundary.json core_tables.
-- Do not edit by hand. A fresh installation runs this file to create the core tables.

CREATE TABLE IF NOT EXISTS agent_issues (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  title TEXT,
  description TEXT,
  source TEXT,
  category TEXT DEFAULT 'optimization',
  priority TEXT DEFAULT 'medium',
  status TEXT DEFAULT 'open',
  linked_session TEXT,
  created_at INTEGER,
  updated_at INTEGER
, pipeline_stage TEXT DEFAULT NULL, predicate_id TEXT, recheck_count INTEGER DEFAULT 0, close_channel TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS idx_agent_issues_open_title ON agent_issues(title) WHERE status = 'open';
CREATE UNIQUE INDEX IF NOT EXISTS idx_agent_issues_open_title_ci ON agent_issues(lower(trim(title))) WHERE status = 'open';
CREATE INDEX IF NOT EXISTS idx_agent_issues_open_title_normalized
  ON agent_issues (lower(trim(title)), id)
  WHERE status = 'open';
CREATE INDEX IF NOT EXISTS idx_agent_issues_title ON agent_issues (title);
CREATE INDEX IF NOT EXISTS idx_issues_created ON agent_issues(created_at);
CREATE INDEX IF NOT EXISTS idx_issues_status ON agent_issues(status, priority);

CREATE TABLE IF NOT EXISTS issue_triage (issue_id INTEGER PRIMARY KEY, rc TEXT NOT NULL, triage_state TEXT NOT NULL DEFAULT 'triaged', owner TEXT NOT NULL, sla_due_at TEXT NOT NULL, triaged_at TEXT DEFAULT (datetime('now')), remediation TEXT, close_evidence TEXT, reopened_count INTEGER NOT NULL DEFAULT 0);

CREATE TABLE IF NOT EXISTS issue_lifecycle (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  issue_id INTEGER NOT NULL,
  event TEXT NOT NULL,
  from_status TEXT,
  to_status TEXT,
  has_evidence INTEGER,
  ts TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
);
CREATE INDEX IF NOT EXISTS idx_issue_lifecycle_issue ON issue_lifecycle (issue_id, ts);
CREATE INDEX IF NOT EXISTS idx_issue_lifecycle_ts_status ON issue_lifecycle (ts, to_status);

CREATE TABLE IF NOT EXISTS remediation_contracts (class TEXT PRIMARY KEY, issue_id INTEGER, precondition TEXT NOT NULL, action TEXT NOT NULL, verify_probe TEXT NOT NULL, verify_transport TEXT NOT NULL, max_attempts INTEGER NOT NULL DEFAULT 3, escalate_to TEXT NOT NULL, expected_cadence_h INTEGER, status TEXT DEFAULT 'active', ts TEXT DEFAULT (datetime('now')), last_attempt_at TEXT, last_verdict TEXT, module TEXT, budget_ms INTEGER DEFAULT 45000, next_due_at TEXT, max_items INTEGER DEFAULT 5, requires_container INTEGER DEFAULT 0, attempts INTEGER DEFAULT 0, deferred_since TEXT);
CREATE INDEX IF NOT EXISTS idx_rc_active_due_transport
  ON remediation_contracts (COALESCE(next_due_at, ts))
  WHERE status IN ('active', 'holding')
    AND verify_transport IN ('d1-query', 'd1-query@portfolio-state', 'external-https');
CREATE INDEX IF NOT EXISTS idx_rc_issue_status ON remediation_contracts (issue_id, status);

CREATE TABLE IF NOT EXISTS work_claims (id INTEGER PRIMARY KEY AUTOINCREMENT, path TEXT NOT NULL, intent TEXT NOT NULL, holder TEXT NOT NULL, issue_id INTEGER, pr INTEGER, claimed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')), expires_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now','+2 hours')), released_at TEXT, outcome TEXT, fence INTEGER);
CREATE INDEX IF NOT EXISTS idx_work_claims_issue ON work_claims (issue_id, released_at);
CREATE INDEX IF NOT EXISTS idx_work_claims_open ON work_claims(released_at, expires_at);
CREATE INDEX IF NOT EXISTS idx_work_claims_path_open ON work_claims(path, released_at, expires_at);

CREATE TABLE IF NOT EXISTS metric_registry (
  metric TEXT PRIMARY KEY,
  layer TEXT NOT NULL,
  kind TEXT NOT NULL,
  formula TEXT,
  source_of_truth TEXT,
  baseline TEXT,
  target TEXT,
  owner TEXT,
  disposition_actor TEXT,
  refresh_cadence TEXT,
  warning_band TEXT,
  kill_band TEXT,
  last_value TEXT,
  last_refreshed TEXT,
  state TEXT
, refresh_class TEXT);

CREATE TABLE IF NOT EXISTS analytics_metric_triggers(id INTEGER PRIMARY KEY AUTOINCREMENT, metric_key TEXT UNIQUE, title TEXT, source_table TEXT, operator TEXT, threshold REAL, priority INTEGER DEFAULT 5, action TEXT, owner TEXT, queue_target TEXT, cooldown_hours INTEGER DEFAULT 168, enabled INTEGER DEFAULT 1, notes TEXT, created_at TEXT DEFAULT (datetime('now')));

CREATE TABLE IF NOT EXISTS tick_runs (
  tick_id TEXT NOT NULL,
  step TEXT NOT NULL,
  ok INTEGER NOT NULL,
  evidence TEXT NOT NULL,
  ts TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  PRIMARY KEY (tick_id, step)
);
CREATE INDEX IF NOT EXISTS idx_tick_runs_ts ON tick_runs (ts);

CREATE TABLE IF NOT EXISTS trust_ledger (
  surface TEXT NOT NULL,
  action_class TEXT NOT NULL,
  ok INTEGER NOT NULL DEFAULT 0,
  fail INTEGER NOT NULL DEFAULT 0,
  trust_score REAL NOT NULL,
  ladder_position TEXT NOT NULL,
  evidence TEXT NOT NULL,
  refreshed_at TEXT NOT NULL,
  PRIMARY KEY (surface, action_class)
);

CREATE TABLE IF NOT EXISTS decision_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  ts TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  actor TEXT NOT NULL,
  assumption TEXT NOT NULL,
  action TEXT NOT NULL,
  evidence TEXT NOT NULL,
  outcome TEXT NOT NULL,
  blast_radius TEXT NOT NULL,
  rollback_path TEXT NOT NULL
, capability_gain TEXT, predicted_outcome TEXT, reach_gain TEXT, surfaces_tested TEXT, outcome_matched INTEGER);

CREATE TABLE IF NOT EXISTS decision_predictions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  decision_id INTEGER NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('metric', 'issue')),
  subject TEXT NOT NULL,
  op TEXT NOT NULL CHECK (op IN ('<', '<=', '>', '>=', '=', 'between', 'closed')),
  value REAL,
  value2 REAL,
  due_at TEXT NOT NULL,
  origin TEXT NOT NULL CHECK (origin IN ('parsed', 'seeded')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  scored_at TEXT,
  observed TEXT,
  matched INTEGER,
  UNIQUE (decision_id, subject, op)
);
CREATE INDEX IF NOT EXISTS idx_decision_predictions_due ON decision_predictions (scored_at, due_at);

CREATE TABLE IF NOT EXISTS decision_outcomes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  decision_id INTEGER NOT NULL,
  ts TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  observed_outcome TEXT NOT NULL,
  matched INTEGER NOT NULL,
  evidence TEXT NOT NULL,
  actor TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS failure_modes (
  fm_key TEXT PRIMARY KEY,
  failure_mode TEXT NOT NULL,
  root_cause TEXT NOT NULL,
  remediation TEXT NOT NULL,
  detector TEXT NOT NULL,
  probe_class TEXT,
  first_seen TEXT NOT NULL,
  issue_id INTEGER
, trigger_condition TEXT, symptom TEXT, blast_radius TEXT);

CREATE TABLE IF NOT EXISTS spof_registry (
  component TEXT PRIMARY KEY,
  critical_path TEXT NOT NULL,
  alternate_path TEXT,
  alternate_tested_at TEXT,
  evidence TEXT NOT NULL,
  issue_id INTEGER,
  reviewed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
);

CREATE TABLE IF NOT EXISTS belief_registry (
  belief_key TEXT PRIMARY KEY,
  claim TEXT NOT NULL,
  confidence REAL,
  evidence TEXT NOT NULL,
  probe_class TEXT NOT NULL,
  built_on TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
);

CREATE TABLE IF NOT EXISTS blocker_redteam (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  target TEXT NOT NULL,
  claim TEXT,
  attempt TEXT NOT NULL,
  verdict TEXT NOT NULL CHECK (verdict IN ('false-belief-removed', 'confirmed-with-evidence', 'workaround-built')),
  evidence TEXT NOT NULL,
  actor TEXT,
  ts TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
, text_sig TEXT);

CREATE TABLE IF NOT EXISTS capability_ledger (
  capability TEXT PRIMARY KEY,
  provenance TEXT NOT NULL,
  prerequisites TEXT,
  reliability TEXT,
  acquired_at TEXT NOT NULL,
  last_exercised_at TEXT,
  evidence TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS doctrine_proposals (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  ts TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  source TEXT NOT NULL UNIQUE,
  signal TEXT NOT NULL,
  proposed_rule TEXT NOT NULL,
  red_team_result TEXT,
  metrics_improved TEXT,
  version TEXT,
  status TEXT NOT NULL DEFAULT 'proposed' CHECK (status IN ('proposed', 'adopted', 'rejected', 'superseded')),
  disposed_at TEXT
);

CREATE TABLE IF NOT EXISTS false_stop_register (
  pattern_key TEXT PRIMARY KEY,
  pattern TEXT NOT NULL,
  cause_class TEXT NOT NULL,
  detection_heuristic TEXT NOT NULL,
  auto_remediation TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
);

CREATE TABLE IF NOT EXISTS control_registry (
  control TEXT PRIMARY KEY,
  location TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('hold', 'filter', 'pause', 'kill-switch', 'gate', 'cap', 'guard', 'lease')),
  guards_against TEXT,
  critical_path INTEGER NOT NULL DEFAULT 0,
  disposition TEXT NOT NULL CHECK (disposition IN ('remove', 'demote', 'replace', 'keep')),
  disposition_state TEXT NOT NULL DEFAULT 'planned' CHECK (disposition_state IN ('planned', 'applied')),
  alternate_path TEXT,
  alternate_tested_at TEXT,
  evidence TEXT NOT NULL,
  issue_id INTEGER,
  reviewed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
);

CREATE TABLE IF NOT EXISTS owner_asks (
  id INTEGER PRIMARY KEY AUTOINCREMENT, plane TEXT NOT NULL, kind TEXT NOT NULL, ref TEXT NOT NULL, question TEXT NOT NULL, cue TEXT,
  options_json TEXT NOT NULL, priority INTEGER DEFAULT 5, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),
  answered_at TEXT, answer TEXT, answer_label TEXT, answered_via TEXT, UNIQUE(kind, ref));
CREATE INDEX IF NOT EXISTS idx_owner_asks_open ON owner_asks (answered_at, plane, priority);

CREATE TABLE IF NOT EXISTS human_actions (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT UNIQUE, title TEXT NOT NULL, why TEXT, default_in_effect TEXT, action TEXT, url TEXT, sev TEXT DEFAULT 'normal', due TEXT, status TEXT DEFAULT 'open', source TEXT, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')), resolved_at TEXT, resolution TEXT, copy_text TEXT);
CREATE INDEX IF NOT EXISTS idx_human_actions_source ON human_actions (source, status);
